const ILLUSTRATION_MAP = { tortilla: TortillaIllustration, paella: PaellaIllustration, gazpacho: GazpachoIllustration };

function IllustrationArt({ emoji, blurred, onUnlock }) {
  const gradients = [
    "linear-gradient(145deg, #E8B84B 0%, #D4622A 50%, #7A3A1A 100%)",
    "linear-gradient(145deg, #6B8B3A 0%, #A8C060 50%, #F5D080 100%)",
    "linear-gradient(145deg, #E87040 0%, #C84820 50%, #7A2810 100%)",
    "linear-gradient(145deg, #5C8B6A 0%, #3A6B4A 50%, #1A3B2A 100%)",
  ];
  const bg = gradients[Math.floor(Math.random() * gradients.length)];
  return (
    <div className="illustration-wrapper" style={{ background: bg, display:"flex", alignItems:"center", justifyContent:"center", position:"relative" }}>
      <span style={{ fontSize:"6rem", filter:"drop-shadow(0 8px 24px rgba(0,0,0,0.3))", position:"relative", zIndex:1 }}>{emoji || "🍽️"}</span>
      <div style={{ position:"absolute", inset:0, background:"radial-gradient(circle at 60% 35%, rgba(255,255,255,0.15), transparent 65%)" }} />
      {blurred && (
        <div className="illustration-blur" onClick={onUnlock}>
          <span className="lock-icon">🔒</span>
          <span>Regístrate gratis para guardar tu receta</span>
          <button className="btn btn-primary btn-sm" style={{ marginTop: 4 }}>Crear cuenta gratis →</button>
        </div>
      )}
    </div>
  );
}

export default function App() {
  const [view, setView] = useState("landing");
  const [user, setUser] = useState(null);
  const [parts, setParts] = useState([]);
  const [isRecording, setIsRecording] = useState(false);
  const [currentText, setCurrentText] = useState("");
  const [pasteText, setPasteText] = useState("");
  const [recipe, setRecipe] = useState(null);
  const [loading, setLoading] = useState(false);
  const [savedRecipes, setSavedRecipes] = useState([]);
  const [showLogin, setShowLogin] = useState(false);
  const [loginEmail, setLoginEmail] = useState("");
  const [selectedRecipe, setSelectedRecipe] = useState(null);

  const recognitionRef = useRef(null);
  const finalTextRef = useRef("");

  useEffect(() => {
    loadSavedRecipes();
  }, []);

  async function loadSavedRecipes() {
    try {
      const result = await window.storage.get("recetario-recipes");
      if (result) setSavedRecipes(JSON.parse(result.value));
    } catch {
      setSavedRecipes([]);
    }
  }

  async function saveRecipe(r) {
    const updated = [{ ...r, id: Date.now(), savedAt: new Date().toLocaleDateString("es-ES") }, ...savedRecipes];
    setSavedRecipes(updated);
    await window.storage.set("recetario-recipes", JSON.stringify(updated));
  }

  function startRecording() {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { alert("Para grabar necesitas abrir esto en Google Chrome 🎙️"); return; }

    finalTextRef.current = "";
    const recognition = new SR();
    recognition.lang = "es-ES";
    recognition.continuous = true;
    recognition.interimResults = true;

    recognition.onresult = (e) => {
      let interim = "";
      let final = finalTextRef.current;
      for (let i = e.resultIndex; i < e.results.length; i++) {
        if (e.results[i].isFinal) {
          final += e.results[i][0].transcript + " ";
          finalTextRef.current = final;
        } else {
          interim += e.results[i][0].transcript;
        }
      }
      setCurrentText(final + interim);
    };

    recognition.onerror = (e) => {
      if (e.error === "not-allowed") {
        alert("Por favor, permite el acceso al micrófono en tu navegador.");
        setIsRecording(false);
      }
    };

    recognition.onend = () => {
      if (recognitionRef.current?.active) {
        try { recognition.start(); } catch(e) {}
      }
    };

    recognition.start();
    recognitionRef.current = { recognition, active: true };
    setIsRecording(true);
  }

  function pauseRecording() {
    if (!recognitionRef.current) return;
    recognitionRef.current.active = false;
    try { recognitionRef.current.recognition.stop(); } catch(e) {}
    // Guardamos el texto ANTES de limpiar
    const text = finalTextRef.current.trim();
    finalTextRef.current = "";
    setCurrentText("");
    setIsRecording(false);
    if (text) {
      setParts(prev => [...prev, { text, id: Date.now() }]);
      return text;
    }
    return "";
  }

  function finishRecording() {
    // Guardamos el texto actual ANTES de llamar a pauseRecording
    const currentSegment = finalTextRef.current.trim();
    if (!recognitionRef.current) return;
    recognitionRef.current.active = false;
    try { recognitionRef.current.recognition.stop(); } catch(e) {}
    finalTextRef.current = "";
    setCurrentText("");
    setIsRecording(false);

    // Combinamos todo: partes anteriores + segmento actual
    setParts(prev => {
      const newParts = currentSegment
        ? [...prev, { text: currentSegment, id: Date.now() }]
        : [...prev];
      const allText = newParts.map(p => p.text).join(" ").trim();
      if (!allText) {
        alert("No he detectado ningún texto. Asegúrate de hablar cerca del micrófono.");
        return prev;
      }
      setTimeout(() => structureRecipe(allText), 100);
      return newParts;
    });
  }

  async function structureRecipe(text) {
    setLoading(true);
    setView("processing");

    try {
      const response = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514",
          max_tokens: 1000,
          messages: [{
            role: "user",
            content: `Eres un asistente que estructura recetas de cocina. Extrae y estructura la siguiente receta en JSON.
RESPONDE SOLO con el JSON, sin texto adicional, sin backticks, sin markdown.

Formato exacto:
{"nombre":"...","descripcion":"descripción breve y apetitosa en 1 frase","tiempo":"...","raciones":"...","ingredientes":["...","..."],"pasos":["...","..."],"consejo":"consejo breve opcional o null","emoji":"un emoji que represente el plato"}

Receta:
${text}`
          }]
        })
      });

      const data = await response.json();
      const rawText = data.content.map(c => c.text || "").join("");
      const cleaned = rawText.replace(/```json|```/g, "").trim();
      const parsed = JSON.parse(cleaned);
      setRecipe(parsed);
      setParts([]);
      setCurrentText("");
      finalTextRef.current = "";
      setView("result");
    } catch (e) {
      console.error(e);
      alert("Hubo un error al procesar la receta. Comprueba que has grabado algo y vuelve a intentarlo.");
      setView("recording");
    }
    setLoading(false);
  }

  function handleLogin(e) {
    e.preventDefault();
    const name = loginEmail.split("@")[0] || "Usuario";
    setUser({ name, email: loginEmail, avatar: loginEmail[0]?.toUpperCase() || "U" });
    setShowLogin(false);
  }

  function handleGoogleLogin() {
    setUser({ name: "María García", email: "maria@gmail.com", avatar: "M" });
    setShowLogin(false);
  }

  function resetToStart() {
    setParts([]);
    setCurrentText("");
    finalTextRef.current = "";
    setRecipe(null);
    setIsRecording(false);
    if (recognitionRef.current) { recognitionRef.current.active = false; try { recognitionRef.current.recognition.stop(); } catch {} }
    setView("landing");
  }

  // ── VIEWS ──────────────────────────────────────────────

  if (view === "processing") {
    return (
      <>
        <style>{STYLES}</style>
        <div className="processing-view fade-up">
          <div className="spinner" />
          <h2>Preparando tu receta...</h2>
          <p>La IA está estructurando todo lo que has contado 🍳</p>
        </div>
      </>
    );
  }

  if (view === "result" && recipe) {
    return (
      <>
        <style>{STYLES}</style>
        <nav>
          <div className="nav-logo" onClick={resetToStart}><span>🫒</span> Mi Recetario</div>
          <div className="nav-actions">
            {user ? (
              <>
                <div style={{ width:36, height:36, borderRadius:"50%", background:"var(--olive)", color:"white", display:"flex", alignItems:"center", justifyContent:"center", fontWeight:600 }}>{user.avatar}</div>
                <button className="btn btn-ghost btn-sm" onClick={() => setView("library")}>Mis recetas</button>
              </>
            ) : (
              <button className="btn btn-secondary btn-sm" onClick={() => setShowLogin(true)}>Iniciar sesión</button>
            )}
          </div>
        </nav>

        <div className="result-view fade-up">
          <button className="result-back" onClick={resetToStart}>← Volver al inicio</button>

          <div className="result-header">
            <div className="recipe-name">{recipe.emoji || "🍽️"} {recipe.nombre}</div>
            {recipe.descripcion && <p className="recipe-desc">{recipe.descripcion}</p>}
            <div className="recipe-meta">
              {recipe.tiempo && <div className="meta-item"><span className="meta-icon">⏱️</span>{recipe.tiempo}</div>}
              {recipe.raciones && <div className="meta-item"><span className="meta-icon">👥</span>{recipe.raciones} raciones</div>}
            </div>
          </div>

          <div className="illustration-card">
            <IllustrationArt
              emoji={recipe.emoji || "🍽️"}
              blurred={!user}
              onUnlock={() => setShowLogin(true)}
            />
            {!user && (
              <div className="save-bar">
                <span className="save-bar-text">Regístrate gratis para desbloquear la ilustración y guardar tus recetas</span>
                <button className="btn btn-primary btn-sm" onClick={() => setShowLogin(true)}>Crear cuenta gratis</button>
              </div>
            )}
          </div>

          <div className="recipe-grid">
            <div className="recipe-section">
              <h3>Ingredientes</h3>
              <ul className="ingredients-list">
                {(recipe.ingredientes || []).map((ing, i) => (
                  <li key={i} className="ingredient-item">
                    <span className="ingredient-dot" />
                    {ing}
                  </li>
                ))}
              </ul>
            </div>
            <div className="recipe-section">
              <h3>Preparación</h3>
              <ol className="steps-list">
                {(recipe.pasos || []).map((paso, i) => (
                  <li key={i} className="step-item">
                    <div className="step-number">{i + 1}</div>
                    <div className="step-text">{paso}</div>
                  </li>
                ))}
              </ol>
            </div>
          </div>

          {recipe.consejo && (
            <div className="tip-box">💡 <strong>Consejo:</strong> {recipe.consejo}</div>
          )}

          {user && (
            <div style={{ marginTop: 40, display: "flex", gap: 12, flexWrap: "wrap" }}>
              <button className="btn btn-olive" onClick={() => { saveRecipe(recipe); setView("library"); }}>
                💾 Guardar en mi recetario
              </button>
              <button className="btn btn-secondary" onClick={resetToStart}>Añadir otra receta</button>
            </div>
          )}
        </div>

        {showLogin && <LoginModal onLogin={handleLogin} onGoogle={handleGoogleLogin} onClose={() => setShowLogin(false)} email={loginEmail} setEmail={setLoginEmail} />}
      </>
    );
  }

  if (view === "recording") {
    const allText = parts.map(p => p.text).join(" ");
    const hasContent = parts.length > 0 || currentText.trim().length > 0;
    return (
      <>
        <style>{STYLES}</style>
        <nav>
          <div className="nav-logo" onClick={resetToStart}><span>🫒</span> Mi Recetario</div>
          <div className="nav-actions">
            <button className="btn btn-ghost btn-sm" onClick={resetToStart}>← Volver</button>
          </div>
        </nav>

        <div className="record-view">
          <div className="record-header fade-up">
            <h2>🎙️ Graba tu receta</h2>
            <p>
              {parts.length === 0 && !isRecording
                ? "Toca el micrófono y empieza a hablar. Puedes pausar cuando quieras."
                : isRecording
                ? "Estás grabando... toca ⏸ para pausar"
                : "Pausado. Toca 🎙️ para seguir grabando, o \"Crear receta\" cuando hayas terminado."}
            </p>
          </div>

          {parts.length > 0 && (
            <div className="parts-list">
              {parts.map((part, i) => (
                <div key={part.id} className="part-chip">
                  <div className="part-number">{i + 1}</div>
                  <div className="part-text">{part.text.length > 120 ? part.text.slice(0, 120) + "…" : part.text}</div>
                </div>
              ))}
            </div>
          )}

          {(isRecording || currentText) && (
            <div className="current-transcript">
              {currentText || <em>Escuchando…</em>}
            </div>
          )}

          <div className="record-controls">
            {isRecording && (
              <div className="waveform">
                {[...Array(9)].map((_, i) => <div key={i} className="wave-bar" />)}
              </div>
            )}

            <button
              className={`record-btn ${isRecording ? "recording" : "idle"}`}
              onClick={isRecording ? pauseRecording : startRecording}
              title={isRecording ? "Pausar" : "Grabar"}
            >
              {isRecording ? "⏸" : "🎙️"}
            </button>

            <div className="record-hint">
              {isRecording ? "Grabando... toca para pausar" : parts.length === 0 ? "Toca el micrófono para empezar" : "Toca para seguir grabando"}
            </div>

            {hasContent && !isRecording && (
              <div className="secondary-controls">
                <button className="btn btn-olive btn-large" onClick={finishRecording}>
                  ✨ Crear mi receta
                </button>
              </div>
            )}
          </div>
        </div>
      </>
    );
  }

  if (view === "paste") {
    return (
      <>
        <style>{STYLES}</style>
        <nav>
          <div className="nav-logo" onClick={resetToStart}><span>🫒</span> Mi Recetario</div>
          <div className="nav-actions">
            <button className="btn btn-ghost btn-sm" onClick={resetToStart}>← Volver</button>
          </div>
        </nav>

        <div className="paste-view fade-up">
          <h2>📋 Pega el texto de tu receta</h2>
          <p>Copia desde WhatsApp, notas del móvil o cualquier lugar. Nosotros lo organizamos.</p>
          <textarea
            placeholder="Escribe o pega aquí la receta... Por ejemplo: Para hacer la tortilla cojo 4 huevos, 3 patatas medianas, media cebolla..."
            value={pasteText}
            onChange={e => setPasteText(e.target.value)}
          />
          <div style={{ marginTop: 20, display: "flex", gap: 12 }}>
            <button
              className="btn btn-primary"
              onClick={() => pasteText.trim() && structureRecipe(pasteText)}
              disabled={!pasteText.trim()}
            >
              ✨ Crear mi receta
            </button>
            <button className="btn btn-secondary" onClick={resetToStart}>Cancelar</button>
          </div>
        </div>
      </>
    );
  }

  if (view === "library") {
    return (
      <>
        <style>{STYLES}</style>
        <nav>
          <div className="nav-logo" onClick={resetToStart}><span>🫒</span> Mi Recetario</div>
          <div className="nav-actions">
            {user && <div style={{ width:36, height:36, borderRadius:"50%", background:"var(--olive)", color:"white", display:"flex", alignItems:"center", justifyContent:"center", fontWeight:600 }}>{user.avatar}</div>}
            <button className="btn btn-primary btn-sm" onClick={resetToStart}>+ Añadir receta</button>
          </div>
        </nav>

        {selectedRecipe ? (
          <div className="result-view fade-up">
            <button className="result-back" onClick={() => setSelectedRecipe(null)}>← Mis recetas</button>
            <div className="recipe-name">{selectedRecipe.emoji || "🍽️"} {selectedRecipe.nombre}</div>
            {selectedRecipe.descripcion && <p className="recipe-desc">{selectedRecipe.descripcion}</p>}
            <div className="recipe-meta">
              {selectedRecipe.tiempo && <div className="meta-item"><span className="meta-icon">⏱️</span>{selectedRecipe.tiempo}</div>}
              {selectedRecipe.raciones && <div className="meta-item"><span className="meta-icon">👥</span>{selectedRecipe.raciones}</div>}
            </div>
            <div className="illustration-card">
              <IllustrationArt emoji={selectedRecipe.emoji || "🍽️"} blurred={false} />
            </div>
            <div className="recipe-grid">
              <div className="recipe-section">
                <h3>Ingredientes</h3>
                <ul className="ingredients-list">
                  {(selectedRecipe.ingredientes || []).map((ing, i) => (
                    <li key={i} className="ingredient-item"><span className="ingredient-dot" />{ing}</li>
                  ))}
                </ul>
              </div>
              <div className="recipe-section">
                <h3>Preparación</h3>
                <ol className="steps-list">
                  {(selectedRecipe.pasos || []).map((paso, i) => (
                    <li key={i} className="step-item">
                      <div className="step-number">{i + 1}</div>
                      <div className="step-text">{paso}</div>
                    </li>
                  ))}
                </ol>
              </div>
            </div>
            {selectedRecipe.consejo && <div className="tip-box">💡 <strong>Consejo:</strong> {selectedRecipe.consejo}</div>}
          </div>
        ) : (
          <div className="library-view fade-up">
            <div className="library-header">
              <h2>📚 Mis recetas guardadas</h2>
              <button className="btn btn-primary" onClick={resetToStart}>+ Añadir receta</button>
            </div>
            {savedRecipes.length === 0 ? (
              <div className="empty-library">
                <div className="emoji">🍳</div>
                <h3>Aún no tienes recetas guardadas</h3>
                <p style={{ marginBottom: 24 }}>Graba o escribe tu primera receta y aparecerá aquí</p>
                <button className="btn btn-primary" onClick={resetToStart}>Añadir mi primera receta</button>
              </div>
            ) : (
              <div className="library-grid">
                {savedRecipes.map(r => (
                  <div key={r.id} className="library-card" onClick={() => setSelectedRecipe(r)}>
                    <div className="library-card-art" style={{ background:"linear-gradient(145deg, #E8B84B, #D4622A)", display:"flex", alignItems:"center", justifyContent:"center", fontSize:"2.8rem" }}>
                      {r.emoji || "🍽️"}
                    </div>
                    <div className="library-card-body">
                      <h4>{r.nombre}</h4>
                      <p>{r.savedAt} · {r.tiempo || "—"}</p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </>
    );
  }

  // ── LANDING ──────────────────────────────────────────────
  return (
    <>
      <style>{STYLES}</style>

      <nav>
        <div className="nav-logo" onClick={resetToStart}><span>🫒</span> Mi Recetario</div>
        <div className="nav-actions">
          {user ? (
            <>
              <div style={{ width:36, height:36, borderRadius:"50%", background:"var(--olive)", color:"white", display:"flex", alignItems:"center", justifyContent:"center", fontWeight:600 }}>{user.avatar}</div>
              <button className="btn btn-secondary btn-sm" onClick={() => setView("library")}>Mis recetas</button>
            </>
          ) : (
            <>
              <button className="btn btn-ghost btn-sm" onClick={() => setShowLogin(true)}>Iniciar sesión</button>
              <button className="btn btn-primary btn-sm" onClick={() => setShowLogin(true)}>Registrarse gratis</button>
            </>
          )}
        </div>
      </nav>

      {/* HERO */}
      <div className="hero">
        <div className="hero-badge fade-up">🍳 Recetas familiares para siempre</div>
        <h1 className="fade-up-1">Guarda las recetas de tu<br /><em>familia para siempre</em></h1>
        <p className="fade-up-2">
          Graba mientras cocinas, con pausas cuando las necesites. La IA lo organiza todo en una receta bonita que no se perderá jamás.
        </p>
        <div className="hero-actions fade-up-3">
          <button className="btn btn-primary btn-large" onClick={() => setView("recording")}>🎙️ Empezar a grabar</button>
          <button className="btn btn-secondary btn-large" onClick={() => { setPasteText(""); setView("paste"); }}>📋 Pegar texto</button>
        </div>
      </div>

      {/* METHODS */}
      <div className="methods-section">
        <h2 className="section-title">¿Cómo quieres añadir tu receta?</h2>
        <p className="section-sub">Elige el método más cómodo para ti</p>
        <div className="methods-grid">
          <div className="method-card fade-up-1" onClick={() => setView("recording")}>
            <span className="method-icon">🎙️</span>
            <div className="method-tag">⭐ Más fácil</div>
            <h3>Graba por partes</h3>
            <p>Graba mientras cocinas. Pausa cuando necesites y continúa después. Sin límite de tiempo, a tu ritmo.</p>
          </div>
          <div className="method-card fade-up-2" onClick={() => setView("paste")}>
            <span className="method-icon">📋</span>
            <div className="method-tag">Rápido</div>
            <h3>Pegar texto</h3>
            <p>¿Te la mandaron por WhatsApp? Pégala aquí y la convertimos en una receta bonita y estructurada.</p>
          </div>
          <div className="method-card fade-up-3" style={{ opacity: 0.7, cursor: "default" }}>
            <span className="method-icon">📷</span>
            <div className="method-tag">Próximamente</div>
            <h3>Escanear foto</h3>
            <p>Haz una foto a una receta escrita a mano y la digitalizamos automáticamente por ti.</p>
          </div>
        </div>
      </div>

      {/* EXAMPLES */}
      <div className="examples-section">
        <div className="examples-inner">
          <h2 className="section-title">Así quedan tus recetas</h2>
          <p className="section-sub">Con ilustración generada por IA, bonita para guardar y compartir</p>
          <div className="examples-grid">
            {EXAMPLE_RECIPES.map((ex, i) => (
              <div key={i} className="example-card">
                <div className="example-illustration">
                  <img src={ex.photo} alt={ex.name} style={{width:"100%",height:"100%",objectFit:"cover",display:"block",transition:"transform 0.4s ease"}} />
                </div>
                <div className="example-card-body">
                  <h4>{ex.name}</h4>
                  <p>{ex.desc}</p>
                  <div className="ingredients-preview">
                    {ex.ingredients.map((ing, j) => <span key={j} className="ingredient-chip">{ing}</span>)}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* PRICING */}
      <div className="pricing-section">
        <h2 className="section-title">Sencillo y sin sorpresas</h2>
        <p className="section-sub">Empieza gratis, mejora cuando quieras</p>
        <div className="pricing-cards">
          <div className="pricing-card fade-up-1">
            <div className="plan-name">Gratis</div>
            <div className="plan-price">0€</div>
            <div className="plan-desc">Para siempre</div>
            <ul className="feature-list">
              <li className="feature-item">Hasta 10 recetas guardadas</li>
              <li className="feature-item">Grabación por partes</li>
              <li className="feature-item">Pegar texto</li>
              <li className="feature-item">Estructuración con IA</li>
            </ul>
            <button className="btn btn-secondary" style={{ width: "100%" }} onClick={() => setShowLogin(true)}>Empezar gratis</button>
          </div>
          <div className="pricing-card featured fade-up-2">
            <div className="plan-name">Premium</div>
            <div className="plan-price">4€ <span>/ mes</span></div>
            <div className="plan-desc">O 35€/año — ahorras 2 meses</div>
            <ul className="feature-list">
              <li className="feature-item">Recetas ilimitadas</li>
              <li className="feature-item">Ilustraciones IA por receta</li>
              <li className="feature-item">Exportar a PDF</li>
              <li className="feature-item">Crear libro de recetas familiar</li>
              <li className="feature-item">Escanear fotos de recetas</li>
            </ul>
            <button className="btn" style={{ background: "white", color: "var(--terracotta)", width: "100%", fontWeight: 600 }}>
              Probar gratis 7 días
            </button>
          </div>
        </div>
      </div>

      {/* FOOTER */}
      <footer>
        <strong>🫒 Mi Recetario</strong> — Las recetas de tu familia, para siempre.<br />
        <span style={{ marginTop: 8, display: "block", fontSize: "0.75rem", opacity: 0.6 }}>Hecho con ❤️ en España</span>
      </footer>

      {showLogin && <LoginModal onLogin={handleLogin} onGoogle={handleGoogleLogin} onClose={() => setShowLogin(false)} email={loginEmail} setEmail={setLoginEmail} />}
    </>
  );
}

function LoginModal({ onLogin, onGoogle, onClose, email, setEmail }) {
  return (
    <div className="modal-overlay" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="modal">
        <h2>Bienvenido/a 🫒</h2>
        <p>Crea una cuenta gratis para guardar tus recetas y desbloquear las ilustraciones</p>
        <button className="google-btn" onClick={onGoogle}>
          <svg width="18" height="18" viewBox="0 0 18 18"><path fill="#4285F4" d="M16.51 8H8.98v3h4.3c-.18 1-.74 1.48-1.6 2.04v2.01h2.6a7.8 7.8 0 002.38-5.88c0-.57-.05-.66-.15-1.18z"/><path fill="#34A853" d="M8.98 17c2.16 0 3.97-.72 5.3-1.94l-2.6-2a4.8 4.8 0 01-7.18-2.54H1.83v2.07A8 8 0 008.98 17z"/><path fill="#FBBC05" d="M4.5 10.52a4.8 4.8 0 010-3.04V5.41H1.83a8 8 0 000 7.18l2.67-2.07z"/><path fill="#EA4335" d="M8.98 4.18c1.17 0 2.23.4 3.06 1.2l2.3-2.3A8 8 0 001.83 5.4L4.5 7.49a4.77 4.77 0 014.48-3.3z"/></svg>
          Continuar con Google
        </button>
        <div className="modal-divider">o con email</div>
        <form onSubmit={onLogin}>
          <input
            className="email-input"
            type="email" placeholder="tu@email.com"
            value={email} onChange={e => setEmail(e.target.value)}
            required
          />
          <button type="submit" className="btn btn-primary" style={{ width: "100%" }}>
            Continuar con email
          </button>
        </form>
        <p style={{ marginTop: 16, fontSize: "0.78rem", color: "var(--brown-light)", marginBottom: 0 }}>
          Al registrarte aceptas los términos de uso. Sin spam, prometido.
        </p>
      </div>
    </div>
  );
}
